  "supportive_card_ids": [
    "C17","C19","C07","C08","C11","C20","C02","C05","C10","C15","C03",
    "C16","C14","C01","C06","C13","C04","C09","C12","C18",
    "C21","C22","C23","C24","C25","C26","C27","C28","C29","C30","C31","C32","C33"
  ],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": [
    "C17","C19","C07","C08","C11","C20","C02","C05","C10","C15","C03",
    "C16","C14","C01","C06","C13","C04","C09","C12","C18"
  ],
  "claims": [
    {
      "claim": "Ketanserin, the closest structural analog sharing the 4-fluorophenyl ketone, piperidine, and fused cyclic-urea motif, has absolute oral bioavailability of 49.3 ± 18.0% (range 27–69%) by the AUC method and about 60% by F = 1 − E in fasted subjects, both clearly above the 20% threshold.",
      "card_ids": ["C17","C19"]
    },
    {
      "claim": "Sertindole, which also combines a piperidine, fluorophenyl, and cyclic-urea heterocycle, has oral bioavailability of approximately 74–75%; L2 records further show tablet relative bioavailability of about 75% and tablet-to-solution relative bioavailability near unity.",
      "card_ids": ["C07","C08","C11","C20","C22","C31"]
    },
    {
      "claim": "Trazodone, sharing a propyl-linked azole-fused cyclic amide and aryl piperazine/piperidine-like scaffold, has absolute oral bioavailability of 63–91% across fasted and fed groups; L2 crossover records report 63–65%.",
      "card_ids": ["C02","C05","C10","C15","C03","C24","C25","C30","C32"]
    },
    {
      "claim": "Maraviroc, a piperidine-containing oral drug, has a population F estimate of 0.24 under fasted conditions at 100 mg and 33% at 600 mg; both values are above the 20% threshold and do not provide affirmative evidence for F < 20%.",
      "card_ids": ["C16","C21","C29"]
    },
    {
      "claim": "Setipiprant, PBA, cerivastatin, BAL27862, and encainide provide additional transferable oral-bioavailability evidence of at least 50–80% (or 0.52 in one poor-metabolizer cirrhosis patient), all above the threshold.",
      "card_ids": ["C14","C23","C26","C01","C28","C06","C13","C04","C09","C12","C18","C27","C33"]
    },
    {
      "claim": "The new L3 oral AUC/Cmax records concern atorvastatin and pitavastatin in microdose/rifampicin studies; these statins are structurally unrelated to the query and the records do not report absolute F, so they do not bear on the query threshold.",
      "card_ids": ["C34","C35","C36","C37","C38","C39","C40","C41","C42","C43","C44","C45"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C34","C35","C36","C37","C38","C39","C40","C41","C42","C43","C44","C45"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query molecule, a benperidol-like butyrophenone/piperidine benzimidazolone.",
    "Query-specific permeability, efflux, and first-pass metabolism data are absent; the physicochemical prior predicts poor passive permeability due to complete ionization and low logD, but this is not affirmative evidence for F < 20%.",
    "Formulation and prandial state for the query are unspecified, while several supporting records are formulation- or prandial-state-dependent.",
    "Structural transfer from analogs is qualitative; no exact structural match is present in the record set.",
    "L3 records are for atorvastatin and pitavastatin under microdose/rifampicin conditions and do not inform the query's F threshold.",
    "L2 records are nonvoting context and do not add independent gold votes, though they reinforce the L1 direction."
  ],
  "decision_summary": "Predicted high (F >= 20%) because multiple transferable L1 absolute-oral-bioavailability records for close structural analogs — especially ketanserin (49–60%), sertindole (~74–75%), trazodone (63–91%), and maraviroc (24–33%) — all meet or exceed the threshold, and no affirmative evidence supports F < 20%. The new L3 oral AUC/Cmax records concern unrelated statins and do not change the decision. Confidence remains moderate because query-specific absorption is uncertain and the physicochemical prior flags a permeability liability."
}

